const originalText = new WeakMap();
const originalAttributes = new WeakMap();
let currentLanguage = localStorage.getItem('tfw-language') === 'en' ? 'en' : 'vi';

function translatedText(value){
  const trimmed=value.trim();
  if(!trimmed)return value;
  let translated=english[trimmed];
  if(!translated){
    const count=trimmed.match(/^(\d+) sản phẩm$/);
    if(count)translated=`${count[1]} products`;
  }
  if(!translated)return value;
  return value.replace(trimmed,translated);
}

function applyLanguage(){
  document.documentElement.lang=currentLanguage;
  document.title=currentLanguage==='en'?'thefirstworkshop — Practical workspace solutions':'thefirstworkshop — Giải pháp không gian làm việc';
  const description=document.querySelector('meta[name="description"]');
  if(description)description.content=currentLanguage==='en'?'thefirstworkshop — furniture and practical workspace solutions for businesses in Vietnam.':'thefirstworkshop — nội thất và giải pháp không gian làm việc cho doanh nghiệp Việt Nam.';
  const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
  let node;
  while((node=walker.nextNode())){
    if(node.parentElement?.closest('#langToggle,script,style,noscript'))continue;
    if(!originalText.has(node))originalText.set(node,node.nodeValue);
    const source=originalText.get(node);
    node.nodeValue=currentLanguage==='en'?translatedText(source):source;
  }
  document.querySelectorAll('[placeholder],[aria-label]').forEach(element=>{
    if(element.id==='langToggle')return;
    if(!originalAttributes.has(element))originalAttributes.set(element,{placeholder:element.getAttribute('placeholder'),ariaLabel:element.getAttribute('aria-label')});
    const source=originalAttributes.get(element);
    if(source.placeholder!==null)element.setAttribute('placeholder',currentLanguage==='en'?({
      'Bàn, ghế, phụ kiện...':'Desks, chairs, accessories...','Nguyễn Minh Anh':'Alex Nguyen','0909 000 000':'0909 000 000','ban@email.com':'you@email.com','Số nhà, đường, phường, quận':'Street, ward, district'
    }[source.placeholder]||source.placeholder):source.placeholder);
    if(source.ariaLabel!==null){let translated=({'Điều hướng chính':'Main navigation','Danh mục sản phẩm':'Product categories','Lọc sản phẩm':'Filter products','Màu hoàn thiện':'Available finishes','Đóng giỏ hàng':'Close cart','Đóng thanh toán':'Close checkout','Đóng tìm kiếm':'Close search','Liên hệ tư vấn':'Request a consultation'}[source.ariaLabel]||source.ariaLabel);translated=translated.replace(/^Thêm (.+) vào giỏ$/,'Add $1 to cart').replace(/^Xem chi tiết (.+)$/,'View $1 details').replace(/^Xem (.+)$/,'View $1').replace(/^Giảm (.+)$/,'Decrease $1').replace(/^Tăng (.+)$/,'Increase $1');element.setAttribute('aria-label',currentLanguage==='en'?translated:source.ariaLabel)}
  });
  const toggle=document.getElementById('langToggle');
  if(toggle){toggle.textContent=currentLanguage==='vi'?'EN':'VI';toggle.setAttribute('aria-label',currentLanguage==='vi'?'Switch to English':'Chuyển sang tiếng Việt')}
  const detailToggle=document.getElementById('detailLangToggle');
  if(detailToggle){detailToggle.textContent=currentLanguage==='vi'?'EN':'VI';detailToggle.setAttribute('aria-label',currentLanguage==='vi'?'Switch to English':'Chuyển sang tiếng Việt')}
}

window.applyI18n=applyLanguage;
document.getElementById('langToggle')?.addEventListener('click',()=>{
  currentLanguage=currentLanguage==='vi'?'en':'vi';
  localStorage.setItem('tfw-language',currentLanguage);
  applyLanguage();
});
applyLanguage();
